export function ingestFranklinTempleton() {
  const cachePath = path.join(process.cwd(), "content/jobs-cache.json");
  const cacheData = JSON.parse(fs.readFileSync(cachePath, "utf8"));
  const descPath = path.join(process.cwd(), "content/job-descriptions.json");
  const descData = fs.existsSync(descPath) ? JSON.parse(fs.readFileSync(descPath, "utf8")) : {};

  let added = 0;
  let updated = 0;

  for (const job of franklinTempletonJobs) {
    if (!isConcreteJobOpening(job.title, job.link)) continue;
    const cleanJob = {
      ...job,
      company: cleanCompanyName(job.company),
    };

    const idx = cacheData.findIndex((j: any) => j.id === cleanJob.id || j.link === cleanJob.link);
    if (idx >= 0) {
      cacheData[idx] = { ...cacheData[idx], ...cleanJob };
      updated++;
    } else {
      cacheData.unshift(cleanJob);
      added++;
    }

    if (job.description) {
      descData[job.id] = job.description;
      const key = getJobContentKey(cleanJob as any);
      descData[key] = job.description;
    }
  }

  console.log(`Ingested Franklin Templeton Jobs: ${added} added, ${updated} updated. Total jobs: ${cacheData.length}`);
  fs.writeFileSync(cachePath, JSON.stringify(cacheData, null, 2));
  fs.writeFileSync(descPath, JSON.stringify(descData, null, 2));
}

if (require.main === module || process.argv[1]?.includes("ingest-franklin-templeton-jobs")) {
  ingestFranklinTempleton();
}
